mapper.select:
SELECT DISTINCT item_key FROM pipeline_item_log
WHERE pipeline_id = #{pipelineId}
  AND status = 'SUCCESS'

SELECT id, pipeline_id AS pipelineId, item_key AS itemKey,
       status, error_node AS errorNode, error_msg AS errorMsg,
       create_time AS createTime
FROM pipeline_item_log
WHERE pipeline_id = #{pipelineId}
  AND status = #{status}
ORDER BY id DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM pipeline_item_log
WHERE pipeline_id = #{pipelineId}
  AND status = #{status}

mapper.delete:
DELETE FROM pipeline_item_log
WHERE pipeline_id IN (
    SELECT id FROM pipeline_task
    WHERE state IN ('COMPLETED', 'FAILED', 'CANCELLED')
      AND create_time < #{before}
)
